  "Sans minimum": "最低限度はない",
  "Cadences du PGN": "PGN 時間制御",
  "Sans maximum": "最大限なし",
  "Aucune coche = toutes les cadences, y compris les inconnues.": "選択なし = 未知を含むすべての時間制御",
  "L’Elo provient du PGN et doit respecter la plage pour les deux joueurs. Sans Elo, une partie est exclue si une borne est définie. Une cadence non renseignée ou non reconnue dans le PGN est « Inconnue ». Ces parties sont exclues si des cadences sont cochées, sauf si « Inconnue » est choisie.": "EloはPGNから生まれ,両プレイヤーの範囲内にある必要があります. Elo以外のチェスのゲームは,境界が設定された場合除外されます. 失踪または認識されていないPGN時間制御は\"未知\"です. \"未知\"を選択しない限り,これらのチェスのゲームは時間制御が選択された場合除外されます.",
  ": indique un nombre valide pour la borne Elo.": ":Elo 字段の有効番号を入力します.",
  ": choisis un Elo entier entre 0 et 4000, ou laisse la borne vide.": ": 0 から 4000 までの整数Elo を入力するか,結束された文字を空白にしてください.",
  ": le minimum Elo ne peut pas dépasser le maximum.": ":最小Eloは最大Eloを超えない.",
  "Crée une base et importe des parties PGN dans la bibliothèque.": "データベースを作成し,図書館にPGNのチェスゲームをインポートします.",
  "Maîtres Lichess ne propose pas de filtre par Elo ou cadence. Pour filtrer une collection de maîtres, choisis une base importée comme Mega Database.": "Lichess マスターには Elo またはタイムコントロールフィルターがない. マスターコレクションをフィルタするには,Mega Databaseなどの輸入データベースを選択します.",
  "Source principale": "主要情報源",
  "Mes bases PGN": "私のPGNデータベース",
  "Seuls les coups joués de la ligne principale sont comptés. Les variantes d’analyse ne gonflent pas les statistiques.": "メインラインのチェスの動きのみがカウントされます. 分析変異は統計を膨らませない.",
  "Référence dans chaque ligne": "各行の参照",
  "Comparer avec": "比較する",
  "Mes bases de référence": "私の参照データベース",
  "Aucune référence": "参照なし",
  "Ces filtres sont indépendants de la base principale. Le pourcentage indique la fréquence du coup à cette position dans la référence choisie.": "これらのフィルターは主データベースから独立します パーセントは,選択した参照のこの位置でチェスの動きの頻度を示します.",
  "Probabilité de rencontre": "遭遇の可能性",
  "Afficher la probabilité de la ligne": "ライン確率を表示する",
  "Choisis ton camp directement dans l’explorateur. Seules les réponses adverses comptent ; tes coups sont supposés joués. Cette estimation suit la variante affichée et les filtres de la base sélectionnée. Pour un PGN démarrant sur un diagramme, elle est conditionnelle à ce départ.": "探査機に直接自分の味方を選んでください 敵の答えだけが重要で チェスの動きは想定されます この推定は,表示された変数と選択されたデータベースフィルターをフォローします. 図から始まるPGNの場合,その出発位置に依存する.",
  "Mode d’analyse": "分析モード",
  "Rapide (~250 ms par coup)": "スピード (チェスの動きあたり~250 ms)",
  "Une profondeur plus élevée affine l’analyse et demande plus de temps. De 8 à 30, avec une limite de 10 secondes par coup. Si la cible n’est pas atteinte, ≈ signale l’évaluation obtenue ; sa profondeur réelle est visible au survol.": "より深いところは分析を改良し 時間がかかるのです 8から30まで チェスの動きごとに10秒制限です 目標が達成されない場合,≈は結果をマークします.",
