  "Choisis les ressources à télécharger, puis lance leur installation.": "ダウンロードするリソースを選択してから、インストールを開始してください。",
  "Ouvre une édition pour télécharger son fichier et l’importer dans ChessGym.": "各エディションを展開してファイルをダウンロードし、ChessGym にインポートしてください。",
