  "Commence avec les exemples, puis ajoute les ressources qui te sont utiles.": "まずサンプルを試してから、必要なリソースを追加しましょう。",
  "Essayer ChessGym en quelques minutes": "数分で ChessGym を試す",
  "Trois petites bases incluses, utilisables sans téléchargement. Leurs lignes et commentaires pédagogiques sont proposés sous CC0.": "ダウンロード不要の小さなデータベースが3つ付属しています。学習用の手順と解説は CC0 で提供されます。",
  "Apprendre une ouverture avec quelques lignes commentées.": "解説付きの短い手順でオープニングを学ぶ。",
  "Retrouver les coups d’une courte partie pédagogique.": "短い練習用の棋譜から次の手を見つける。",
