  "Ouvrir {activity}": "{activity}を開く",
  "Tes bases d’exemples sont prêtes. Tes modifications et ta progression sont conservées.": "サンプルデータベースの準備ができました。変更内容と進捗は保持されます。",
  "Stockfish est nécessaire pour noter les coups dans Guess the Move. Le répertoire et la lecture sont disponibles sans moteur.": "Guess the Move の手の採点には Stockfish が必要です。レパートリーと読書はエンジンなしで利用できます。",
  "Recommandé pour commencer": "最初におすすめ",
  "Facultatif · adversaire au style humain": "任意 · 人間らしい棋風の対戦相手",
  "Stockfish active l’analyse et Guess the Move. Maia est facultatif pour jouer contre un adversaire au style humain. Aucun téléchargement ne commence avant ton choix.": "Stockfish は解析と Guess the Move に使用します。Maia は人間らしい棋風の相手と対局するための任意の機能です。選択するまでダウンロードは始まりません。",
  "Exemples ajoutés. Choisis une activité pour commencer.": "サンプルを追加しました。開始するアクティビティを選んでください。",
