  "Choisis une période valide de 730 jours au maximum.": "730 日以内の有効な期間を選んでください。",
  "Sélectionne une activité pour explorer ton temps.": "アクティビティを選ぶと、使った時間を確認できます。",
  "Aucune durée mesurée sur cette période. Les nouvelles activités apparaîtront ici automatiquement.": "この期間には計測された時間がありません。新しいアクティビティは自動的にここに表示されます。",
  "{count} activité(s) ont une durée inconnue. Elles ne sont pas comptées comme zéro.": "{count} 件のアクティビティは所要時間が不明です。0 としては計上しません。",
