  "Le temps au fil des jours": "日々の時間の推移",
  "Chaque couleur représente une activité. Survole une barre pour voir sa durée.": "色ごとにアクティビティを表します。棒にポインターを合わせると時間が表示されます。",
  "Temps enregistré par période et par activité": "期間別・アクティビティ別の記録時間",
