  "RAM détectée : {memory} Mo. Réserve système : {reserve} Mo.": "検出した RAM：{memory} MB。システム用の予約容量：{reserve} MB。",
  "RAM non détectée : le cache Stockfish est limité à 128 Mo par prudence.": "RAM を検出できませんでした。余裕を持たせるため、Stockfish のキャッシュを 128 MB に制限しています。",
  "Ces ressources sont celles du serveur ChessGym, pas de l’appareil qui affiche cette page.": "これは ChessGym サーバーのリソースで、このページを表示している端末のものではありません。",
  "Équilibré (recommandé)": "バランス（推奨）",
  "Les profils recommandés laissent de la capacité pour les autres applications. Choisis Personnalisé pour ajuster les valeurs.": "推奨プロファイルでは、ほかのアプリ用にリソースを残します。値を調整するには「カスタム」を選んでください。",
  "Budget CPU (cœurs logiques)": "CPU 使用枠（論理コア数）",
  "Cache mémoire Stockfish total (Mo)": "Stockfish のメモリキャッシュ合計（MB）",
  "Le cache mémoire est partagé entre les deux moteurs Stockfish. Ce réglage ne plafonne pas la RAM totale de ChessGym : Maia, les imports et l’interface utilisent aussi de la mémoire.": "メモリキャッシュは 2 つの Stockfish エンジンで共有します。この設定は ChessGym 全体の RAM 使用量を制限するものではありません。Maia、インポート、画面表示もメモリを使います。",
  "Le budget CPU est partagé entre les calculs et les imports. Les tâches attendent si le budget est déjà utilisé. Les changements s’appliquent aux prochaines tâches.": "CPU 使用枠は計算とインポートで共有します。使用枠が埋まっている場合、タスクは待機します。変更は次のタスクから適用されます。",
  "La configuration enregistrée a été adaptée aux ressources de ce serveur.": "保存済みの設定を、このサーバーのリソースに合わせて調整しました。",
  "Choix : {cores} cœurs logiques, {memory} Mo de cache et {workers} processus d’importation.": "選択内容：論理コア {cores} 個、キャッシュ {memory} MB、インポートプロセス {workers} 個。",
  "Avec ce petit budget CPU, certaines analyses et importations se déroulent l’une après l’autre.": "この小さな CPU 使用枠では、一部の解析とインポートを順番に実行します。",
  "Choisis un nombre de cœurs compris dans les limites de ce serveur.": "このサーバーの上限内でコア数を選んでください。",
  "Choisis une quantité de mémoire cache comprise dans les limites de ce serveur.": "このサーバーの上限内でキャッシュ容量を選んでください。",
  "Choisis un nombre de processus d’importation compris dans les limites de ce serveur.": "このサーバーの上限内でインポートプロセス数を選んでください。",
  "Le nombre de processus d’importation dépasse le budget CPU choisi.": "インポートプロセス数が選択した CPU 使用枠を超えています。",
  "La durée doit être un nombre positif d’au moins 0,1 seconde.": "時間は 0.1 秒以上の正の数で指定してください。",
  "La profondeur doit être un entier positif accepté par le moteur.": "深さはエンジンが対応する正の整数で指定してください。",
  "La durée doit être un nombre entier de millisecondes positif.": "時間はミリ秒単位の正の整数で指定してください。",
  "Choisis le mode rapide ou une profondeur Stockfish entière positive.": "高速モードを選ぶか、Stockfish の深さを正の整数で指定してください。",
  "Choisis une profondeur entière positive, ou le mode rapide.": "深さを正の整数で指定するか、高速モードを選んでください。",
  "La profondeur doit être un entier positif compatible avec le moteur.": "深さはエンジンと互換性のある正の整数で指定してください。",
  "Le temps par position doit être un entier d’au moins 100 ms, représentable sans perte.": "局面ごとの時間は、精度を損なわずに表現できる 100 ミリ秒以上の整数で指定してください。",
  "Choisis une durée ou une profondeur pour analyser la partie.": "対局を解析する時間または深さを選んでください。",
  "Choisis une profondeur positive. Le calcul continue jusqu’à cette cible, sans limite de temps ajoutée. Une profondeur élevée peut demander longtemps ; tu peux arrêter les évaluations ou changer de position.": "正の深さを選んでください。追加の時間制限を設けず、その深さまで計算を続けます。深く読むには長い時間がかかる場合があります。評価を停止するか、局面を変えると中止できます。",
  "Choisis une profondeur entière positive compatible avec le moteur.": "エンジンが対応する正の整数で深さを指定してください。",
  ", sans limite de temps ajoutée. ≈ indique une cible non atteinte.": "、追加の時間制限なし。≈ は目標に達していないことを示します。",
  " non atteinte": " 未到達",
  "Durée par position": "局面ごとの時間",
  "En mode profondeur, chaque position est analysée jusqu’à la cible, sans limite de temps ajoutée. En mode durée, le calcul utilise le temps choisi. Tu peux continuer à utiliser ChessGym ou annuler le bilan.": "深さモードでは、追加の時間制限を設けず、各局面を目標の深さまで解析します。時間モードでは、選択した時間で計算します。ChessGym を使い続けることも、レポートの作成を中止することもできます。",
  "Choisis une durée d’au moins 0,1 seconde, avec au plus trois décimales.": "時間は 0.1 秒以上、小数点以下 3 桁以内で指定してください。",
  "Choisis une durée, une profondeur cible ou un calcul sans limite.": "時間、目標深さ、または無制限の計算を選んでください。",
  "Le calcul vise cette profondeur sans limite de temps. La profondeur atteignable dépend du moteur.": "時間制限を設けず、この深さを目指して計算します。到達できる深さはエンジンによって異なります。",
  "Désactive le moteur ou change de position pour arrêter le calcul.": "計算を止めるには、エンジンを無効にするか、局面を変えてください。"
